reference_solution:
from collections import Counter
def leastInterval(tasks, n):
    if not tasks:
        return 0
    c = Counter(tasks)
    maxf = max(c.values())
    cnt = sum(1 for v in c.values() if v == maxf)
    return max((maxf - 1) * (n + 1) + cnt, len(tasks))

